import{_ as e,o,c as d,a2 as s}from"./chunks/framework.yO0biSGH.js";const g=JSON.parse('{"title":"P6 · Capstone：go 版 dnsproxi（对照你的 Rust 载体 D1-D7）","description":"","frontmatter":{"title":"P6 · Capstone：go 版 dnsproxi（对照你的 Rust 载体 D1-D7）"},"headers":[],"relativePath":"p6-capstone-dnsproxi.md","filePath":"p6-capstone-dnsproxi.md","lastUpdated":1793119197000}'),a={name:"p6-capstone-dnsproxi.md"};function r(c,t,i,n,l,h){return o(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="p6-·-capstone-go-版-dnsproxi-对照你的-rust-载体-d1-d7" tabindex="-1">P6 · Capstone：go 版 dnsproxi（对照你的 Rust 载体 D1-D7） <a class="header-anchor" href="#p6-·-capstone-go-版-dnsproxi-对照你的-rust-载体-d1-d7" aria-label="Permalink to &quot;P6 · Capstone：go 版 dnsproxi（对照你的 Rust 载体 D1-D7）&quot;">​</a></h1><blockquote><p>你在 <code>_rust_learning</code> 线⑤用 Rust 把 dnsproxi 从 D1 写到 D7（负缓存、 TinyLFU 准入、主动老化，24 个单测、全部实测）。现在用 Go 复刻， <strong>每一课都有你自己的 Rust 代码做对照</strong>：这是这套课的收官项目。</p></blockquote><h2 id="怎么读这章" tabindex="-1">怎么读这章 <a class="header-anchor" href="#怎么读这章" aria-label="Permalink to &quot;怎么读这章&quot;">​</a></h2><p>这是一份工程复盘日志，不是教程：G1 到 G6 每一段都是一次实测验收 （跑通什么、数字是多少）加教训（翻车在哪、修法是什么）。按 G1→G6 顺序读，起手小节告诉你下一步装什么，复盘小节给实拍表格和 Go vs Rust 实感。文中的阶段规划表保留原样；&quot;对照你 Rust 版&quot;全部指向 _rust_learning 线⑤的 D1-D7 代码。复盘内容未改写，历史价值在原话。</p><h2 id="为什么是-dnsproxi" tabindex="-1">为什么是 dnsproxi <a class="header-anchor" href="#为什么是-dnsproxi" aria-label="Permalink to &quot;为什么是 dnsproxi&quot;">​</a></h2><ul><li><strong>UDP 无连接 + 每查询临时 socket</strong>（D1）→ goroutine 生死管理和 channel 的天然练习</li><li><strong>共享缓存</strong>（D2-D7）→ P3 的 sync 决策树 + 你 D4 sample-K、D5 FreqSketch 在 Go 里重写一遍（<code>atomic.Pointer</code> 换 ArcSwap，<code>sync.Map</code>/分片锁换 RwLock）</li><li><strong>TTL 主动老化</strong>（D6）→ time.Ticker + 后台 goroutine 的生命周期管理</li><li><strong>字节解析</strong>（DNS 报文头、压缩指针）→ Go 的 <code>encoding/binary</code> + <code>[]byte</code> 切片，对照 Rust 的 <code>&amp;[u8]</code> + try_get：<strong>没有借用检查的世界里 怎么安全切 buffer</strong>，这是 Go 的核心功课</li></ul><h2 id="阶段规划-对应你的-rust-课程线" tabindex="-1">阶段规划（对应你的 Rust 课程线） <a class="header-anchor" href="#阶段规划-对应你的-rust-课程线" aria-label="Permalink to &quot;阶段规划（对应你的 Rust 课程线）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>对照 Rust</th><th>新学 Go 点</th></tr></thead><tbody><tr><td>G1</td><td>UDP 转发 + sinkhole</td><td>D1</td><td><code>net.ListenUDP</code>、<code>ReadFromUDP</code>、per-query goroutine、<code>net.Resolver</code></td></tr><tr><td>G2</td><td>应答缓存 (qname,qtype)+TTL 倒计时</td><td>D2</td><td><code>map</code>+<code>sync.RWMutex</code>、<code>time.Now</code> 单调钟</td></tr><tr><td>G3</td><td>容量上限 + sample-K 逐出</td><td>D3/D4</td><td><code>atomic.Int64</code>、<code>math/rand</code>、slots 索引</td></tr><tr><td>G4</td><td>TinyLFU 准入（CMS+挡板+老化）</td><td>D5</td><td>位图操作 <code>[]uint64</code>、CAS</td></tr><tr><td>G5</td><td>TTL 主动老化 + 负缓存</td><td>D6/D7</td><td><code>time.Ticker</code>、优雅关停（P3/P5 套路）</td></tr><tr><td>G6</td><td>同机压测：Go vs Rust dnsproxi</td><td>L8 方法论</td><td><code>go test -bench</code>、pprof</td></tr></tbody></table><p><strong>验收标准</strong>（沿用你的规矩）：每阶段 <code>go test</code> 全绿 + <code>run.sh</code> 场景可复跑 + 数字能对上你 Rust 版的量级（否则查为什么，这就是 Lesson）。</p><h2 id="实装收官-g1-g6-全部完成-读数见-dnsproxi-go-lesson-md" tabindex="-1">实装收官（G1-G6 全部完成，读数见 dnsproxi-go/LESSON.md） <a class="header-anchor" href="#实装收官-g1-g6-全部完成-读数见-dnsproxi-go-lesson-md" aria-label="Permalink to &quot;实装收官（G1-G6 全部完成，读数见 dnsproxi-go/LESSON.md）&quot;">​</a></h2><p><code>dnsproxi-go/</code>（module <code>golearn/dnsproxi-go</code>，最终形态）：</p><ul><li><code>main.go</code>：env 配置 + <code>Proxy</code>（UDP 转发/sinkhole/缓存接入）+ 优雅关停</li><li><code>wire/wire.go</code>：DNS 报文解析（header/question/rr，压缩指针防御）</li><li><code>cache/</code>：G2-G4 全套（Cache+RWMutex、sample-K 逐出、TinyLFU CMS+老化）</li><li><code>logger.go</code>/<code>metrics.go</code>：P15/P17 落地（ctx 日志、RED 指标）</li><li><code>dnsq/</code>：UDP 压测发包器（G6 数据的来源）</li><li><code>run.sh</code>：场景复跑入口</li></ul><p>毕业时的目录和课程开始时&quot;骨架加待填占位&quot;的初始形态不同：转发器长在 <code>main.go</code> 的 <code>Proxy</code> 里（单文件比拆 proxy.go 更贴 D1 规模），测试在 <code>main_test.go</code>/<code>trace_test.go</code>/<code>wire/</code>/<code>cache/</code>。</p><h2 id="d1-验收场景-对应你-rust-版-run-sh-query-wire-block" tabindex="-1">D1 验收场景（对应你 Rust 版 run.sh query/wire/block） <a class="header-anchor" href="#d1-验收场景-对应你-rust-版-run-sh-query-wire-block" aria-label="Permalink to &quot;D1 验收场景（对应你 Rust 版 run.sh query/wire/block）&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dnsproxi-go/...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 单测全绿</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dnsproxi-go</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 起 :5353</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5353</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 走通四跳</span></span></code></pre></div><h2 id="对照阅读表-写-go-时开着你的-rust-源码" tabindex="-1">对照阅读表（写 Go 时开着你的 Rust 源码） <a class="header-anchor" href="#对照阅读表-写-go-时开着你的-rust-源码" aria-label="Permalink to &quot;对照阅读表（写 Go 时开着你的 Rust 源码）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Go 代码</th><th>Rust 对照</th><th>关注点</th></tr></thead><tbody><tr><td><code>wire/wire.go</code>（Header/ParseName）</td><td><code>main.rs</code> 头部解析 + <code>parse_qname</code></td><td><code>binary.BigEndian.Uint16</code> vs <code>u16::from_be_bytes</code>；压缩指针 <code>[]byte</code> 无借用检查：offset 越界=panic，要显式防御</td></tr><tr><td><code>main.go</code>（Run/handleQuery）</td><td><code>main.rs</code> 转发循环</td><td>生命周期由等待和上游 deadline 控制；<code>-race</code> 检测竞争，不检测 goroutine 泄漏</td></tr><tr><td><code>cache/cache.go</code></td><td><code>CacheStore</code></td><td><code>sync.RWMutex</code> vs <code>RwLock&lt;HashMap&gt;</code>，锁粒度选择</td></tr><tr><td><code>cache/sketch.go</code></td><td><code>FreqSketch</code></td><td>位运算一样，但 Go 没有.checked_add，要手动防溢出</td></tr></tbody></table><h2 id="g2-复盘-2026-10-09-实测完成" tabindex="-1">G2 复盘（2026-10-09 实测完成） <a class="header-anchor" href="#g2-复盘-2026-10-09-实测完成" aria-label="Permalink to &quot;G2 复盘（2026-10-09 实测完成）&quot;">​</a></h2><p>实装范围：<code>cache/</code> 包（Key/Entry/Cache + ParseQuestion/Records/Request/ PlanResponse + Reply）+ main.go 接入（DNS_CACHE=1 开关、命中不转发、 上游应答入库）+ run.sh cache 冒烟场景（fake upstream 加 per-name 计数）。</p><h3 id="实测结果" tabindex="-1">实测结果 <a class="header-anchor" href="#实测结果" aria-label="Permalink to &quot;实测结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>结果</th></tr></thead><tbody><tr><td><code>go test -race -count=1 ./cache/</code></td><td>9 测全绿（含并发读写 race 检查）</td></tr><tr><td>dig#1（miss）</td><td>上游 <code>[upstream] cache.test type=1 hit=1</code>，应答 TTL 60</td></tr><tr><td>dig#2（1s 后）</td><td><strong>代理日志 <code>msg:&quot;cache hit&quot; ttl_left=59</code>（slog JSON），dig 显示 TTL 59，上游零包</strong></td></tr><tr><td>dig#3（62s 后）</td><td>已过期 → 上游 hit=2，TTL 回到 60</td></tr><tr><td>裸 UDP 客户端（python）</td><td>第 2 查即命中，上游只见 1 包</td></tr></tbody></table><h3 id="go-vs-rust-实感-对照你-rust-版-d2" tabindex="-1">Go vs Rust 实感（对照你 Rust 版 D2） <a class="header-anchor" href="#go-vs-rust-实感-对照你-rust-版-d2" aria-label="Permalink to &quot;Go vs Rust 实感（对照你 Rust 版 D2）&quot;">​</a></h3><ol><li><strong>解析器从&quot;函数返回 Option&quot;变成&quot;结构体 + error&quot;</strong>。Rust 版 <code>question()/records()</code> 返回 <code>Option&lt;(String,u16,usize)&gt;</code>，一行 <code>?</code> 走完； Go 版 ParseQuestion 返回 <code>*Question</code> 结构体，每个字段显式赋值。代码长 30%，但调用点可读性反而高：<code>q.Name</code> vs <code>q.0</code>。</li><li><strong>Entry 是纯值类型，不需要 AtomicU64</strong>。Rust 版 last_access 是 <code>AtomicU64</code>（读锁下原子写，近似 LRU）；Go 版 D2 档直接砍掉这个字段， 惰性过期 + RWMutex 读路径零写。AtomicU64 是 D3 sample-K 的前置，到时候 Go 用 sync/atomic 照抄 fetch_max 语义。</li><li><strong>TTL 倒计时的偏移不变量，两个语言都要手工维护</strong>。<code>question 段长度 必须相等，否则指针偏移错位</code> 这个判据，Rust 用 <code>end != old_end</code> 三行， Go 同样三行。跨语言教训：<strong>字节级协议的不变量检查是语言无关的</strong>， 谁都逃不掉，谁都不能偷懒。</li><li><strong>冒烟踩坑（比 Rust D2 深一层）</strong>：macOS dig 9.10.6 默认置 EDNS OPT （ARCOUNT=1）+ <strong>AD 位</strong>（byte3=0x20）。+noedns 消 EDNS、+cd 消不掉 AD（只加 CD），<strong>+noad 才是&quot;纯 RD=1 查询&quot;</strong>。cache.Request 拒收 flags2!=0 是刻意的（对齐你 Rust 版 <code>buf[3] != 0</code>），冒烟脚本的 dig 参数就是这节课的作业答案。定位手法：裸 python 客户端一发即中（hit）， dig 两发全 miss → 差异在客户端 flags → hex dump 上游收到的包 （<code>0120</code> vs <code>0100</code>）→ 对表 AD 位。</li><li><strong>fake upstream 升级为带计数</strong>。<code>collections.Counter</code> per-(qname,qtype) 计数，每次查询打 <code>[upstream] qname type=T hit=N</code>。这行输出就是缓存 端到端的<strong>判据</strong>（上游只见 2 次 = miss + 过期重取）；对照你 Rust 版 run.sh 里靠 dnsq.py 输出 answers 字段逐发人工对账（D1 线的 dns-upstream 本身不带计数，这个 Counter 是 Go 版新加的）。 测试基础设施一开始就为可观测性服务。</li></ol><h3 id="g3-起手" tabindex="-1">G3 起手 <a class="header-anchor" href="#g3-起手" aria-label="Permalink to &quot;G3 起手&quot;">​</a></h3><p>对照你 Rust 版 main.rs 的 CacheStore/keys+slots：D3 容量上限 + sample-K 逐出。Go 版 keys 用 <code>[]Key</code> + <code>map[Key]int</code>（slot 反查），swap_remove 语义 Go 切片直接对应。入口：<code>cache/evict.go</code> + <code>DNS_CACHE_MAX</code>/ <code>DNS_CACHE_SAMPLE_K</code> 两个 env。</p><h2 id="收官" tabindex="-1">收官 <a class="header-anchor" href="#收官" aria-label="Permalink to &quot;收官&quot;">​</a></h2><p>G6 做完，把 Go 版和 Rust 版同机压测（Go 版自带 <code>dnsq/</code> 压测器， Rust 侧可复用 dnsq.py）， 结论写进 <code>dnsproxi-go/LESSON.md</code>，那就是你这门课的毕业论文。</p><h2 id="g4-复盘-2026-10-09-实测完成" tabindex="-1">G4 复盘（2026-10-09 实测完成） <a class="header-anchor" href="#g4-复盘-2026-10-09-实测完成" aria-label="Permalink to &quot;G4 复盘（2026-10-09 实测完成）&quot;">​</a></h2><p>实装范围：<code>cache/sketch.go</code>（FreqSketch：CMS 4 行 × 4bit、16 格打包 uint64、spread 雪崩哈希、doorkeeper bloom、老化减半 + size 修正、 Admit 判决）+ PutFull 两值返回（Eviction/Rejected）+ main.go 接线 （DNS_CACHE_ADMIT/DOORKEEPER env、cache reject 日志、命中也计数）。</p><h3 id="实测结果-1" tabindex="-1">实测结果 <a class="header-anchor" href="#实测结果-1" aria-label="Permalink to &quot;实测结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>结果</th></tr></thead><tbody><tr><td><code>go test -race -count=1 ./cache/</code></td><td>全绿（10 个 G4 测试：计数/取min 合一/挡板/减半/老化解锁/判决/死人不守门/门控冷拒/门控热进/并发/回归关准入）</td></tr><tr><td>admit 冒烟：hot1/hot2 各 5 查养热</td><td>频率到 5，hit 全中</td></tr><tr><td>冷名 cold.test 撞满仓</td><td><code>msg:&quot;cache reject&quot; qname:&quot;cold.test&quot; cand_freq=1 victim_freq=5</code>（没进缓存），<strong>两次都被拒</strong></td></tr><tr><td>缓存完整性</td><td>被拒插入后 hot1/hot2 原封不动（缓存一字未动的语义落地）</td></tr><tr><td>上游计数</td><td>hot1×1、hot2×1、cold×2，准入生效的判据</td></tr></tbody></table><h3 id="go-vs-rust-实感-对照你-rust-版-d5" tabindex="-1">Go vs Rust 实感（对照你 Rust 版 D5） <a class="header-anchor" href="#go-vs-rust-实感-对照你-rust-版-d5" aria-label="Permalink to &quot;Go vs Rust 实感（对照你 Rust 版 D5）&quot;">​</a></h3><ol><li><strong>AtomicU64 数组 → atomic.Uint64 切片</strong>。Rust <code>Vec&lt;AtomicU64&gt;</code> 一行； Go <code>make([]atomic.Uint64, n)</code> 同样直白（atomic.Uint64 是 Go 1.19+ 的 对应物，别用 <code>[]uint64</code>+atomic.LoadPointer 自虐）。CAS 循环照抄： <code>CompareAndSwap(cur, cur+1&lt;&lt;shift)</code>，饱和判据 <code>(cur&gt;&gt;shift)&amp;0xF == 0xF</code>。 位运算部分两语言逐字同构，你 Rust 课文说&quot;位运算一样&quot;，实测如此。</li><li><strong>fetch_update → Load+Swap</strong>。Rust 减半用 <code>fetch_update</code>（CAS 到成功）；Go 版采用 <code>Swap((Load()&gt;&gt;1)&amp;mask)</code>，可能覆盖并发增量，这是近似计数的一项取舍，不能推广成精确计数的安全替代。</li><li><strong>pickVictim 的 expired 判据</strong>。你 Rust 版是 <code>DNS_CACHE_VICTIM_EXPIRED_FIRST</code> 旋钮 + 排序键字典序；Go 版简化成 &quot;始终检查挑中者死活&quot;（排序仍纯 last_access）。少一个旋钮、语义同向： 尸体在准入里无条件输。D6 上主动老化时再评估要不要补字典序。</li><li><strong>翻车×2，都被测试抓住</strong>：① <code>pickVictim</code> 里调了两次 <code>sampleIndices</code> （一次建 candidates、一次换算下标），RNG 前进导致两个不同的样本， 下标换算全乱。修法：只调一次，统一成&quot;候选下标集合&quot;。教训同 D3： <strong>RNG 是状态机，调两次就漂移</strong>。② NewSketch 的 doorMask 三目表达式 手滑写进 doorMark 函数体，gofmt 过了但 vet 报语法错，说明<strong>格式化 工具不背语法正确性的锅</strong>。</li><li><strong>准入的语义红利在日志里看得见</strong>：<code>msg:&quot;cache reject&quot; qname:cold.test cand_freq=1 victim_freq=5</code> 这行日志同时给出了判决依据（双方频率）和结果。 可观测性不是事后加的，是判决函数顺手返回的（Admit 只返回 bool， 频率在 PutFull 里已知，日志信息零成本）。</li></ol><h3 id="g5-起手" tabindex="-1">G5 起手 <a class="header-anchor" href="#g5-起手" aria-label="Permalink to &quot;G5 起手&quot;">​</a></h3><p>对照你 Rust 版 D6：主动老化（Redis activeExpireCycle）。Go 版 <code>cache/expire.go</code>：time.Ticker 每 1/hz 秒醒，每轮随机抽 sample 个 slot 当场判当场删（<strong>一次抽一个，不能先攒批再删</strong>：swap_remove 会让记住的 下标指向别人，静默删活人），25% 过期率高就再来一轮，墙钟预算用完就停。 入口：<code>DNS_CACHE_ACTIVE_TTL</code>/<code>DNS_CACHE_EXPIRE_HZ</code>。</p><h2 id="g5-复盘-2026-10-10-实测完成" tabindex="-1">G5 复盘（2026-10-10 实测完成） <a class="header-anchor" href="#g5-复盘-2026-10-10-实测完成" aria-label="Permalink to &quot;G5 复盘（2026-10-10 实测完成）&quot;">​</a></h2><p>实装范围：<code>cache/expire.go</code>（ExpireRound/ExpireCycle/RunExpirer/Ghosts + ExpireCfg 默认值考据）+ Cache 账本扩展（ExpiredActive/ExpireChecked/ ExpireCycles/ExpireRounds/ExpireUs）+ main.go 接线（DNS_CACHE_ACTIVE_TTL 等 5 个 env、envIntClamp 越界回退、expire round 日志（DNS_CACHE_EXPIRE_LOG 开到 debug 档）、defer 关停链）+ run.sh expire 场景。</p><h3 id="实测结果-2" tabindex="-1">实测结果 <a class="header-anchor" href="#实测结果-2" aria-label="Permalink to &quot;实测结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>结果</th></tr></thead><tbody><tr><td><code>go test -race -count=1 ./cache/</code></td><td>全绿（7 个 G5 测试：只收尸体/换位陷阱 800 条压测/空表+sample=0/雪崩多轮/低过期率一轮停/关停/并发不 race）</td></tr><tr><td>雪崩测试</td><td>300 条全死 → 多轮清空，<code>rounds&gt;=2</code>（10% 判据触发续轮）</td></tr><tr><td>低过期率</td><td>100 活 + 1 死 → <code>rounds==1</code>（自适应生效：低 stale 不空转）</td></tr><tr><td>expire 冒烟</td><td>ghost.test 首查 miss→上游 hit=1；62s 后 <code>msg:&quot;expire round&quot; rounds=2 checked=1 removed=1</code>；再查 miss→上游 hit=2（尸体确认被收走）</td></tr><tr><td>全仓回归</td><td>go vet + <code>go test -race ./...</code> 三包全绿，gofmt 零 diff</td></tr></tbody></table><h3 id="go-vs-rust-实感-对照你-rust-版-d6" tabindex="-1">Go vs Rust 实感（对照你 Rust 版 D6） <a class="header-anchor" href="#go-vs-rust-实感-对照你-rust-版-d6" aria-label="Permalink to &quot;Go vs Rust 实感（对照你 Rust 版 D6）&quot;">​</a></h3><ol><li><strong>结构同构，goroutine 替代 tokio::spawn</strong>。你 Rust 版 <code>tokio::spawn</code><ul><li><code>interval(Duration::from_millis(1000/hz))</code>；Go 版 <code>time.NewTicker</code></li><li>goroutine + <code>done</code> channel 关停。间隔算术两版同款 <code>1000/hz</code> 毫秒 ：两版都要限制 hz；Go 的 <code>time.Second / time.Duration(hz)</code> 在 hz=0 时整数除零会 panic，hz 过大时计算出的间隔也可能为零，<code>NewTicker</code> 不接受非正间隔。因此 envIntClamp 的范围限制不能省。</li></ul></li><li><strong>锁边界翻译得更直白</strong>。Rust 版 <code>let (checked, removed) = { let mut c = cache.write(); c.expire_round(...) };</code>：花括号就是锁的生死线。 Go 版 ExpireRound 自带 <code>Lock/defer Unlock</code>，多轮之间锁天然释放， 排队的查询能插进来。语言没有作用域锁的语法糖，反而逼你把边界 想清楚：每轮一个函数，锁的边界 = 函数边界。</li><li><strong>Pct 默认 10 不是 25</strong>。你 Rust :857-864 的源码考据先行：25 是 SLOW_TIME_PERC（CPU 预算百分比），现行 Redis 判据是 ACCEPTABLE_STALE=10，坊间的 25% 是两个常量张冠李戴。Go 版注释 直接引用这个考据：先查证再写默认值。</li><li><strong>测试翻车×1：不是 bug，是抽样统计</strong>。换位陷阱测试期望 50 轮收干净 200 具尸体，实测 removed=163：有放回 20 抽/轮 × 50 轮 = 1000 抽， 本来就覆盖不满 200/800 密度的全部尸体（探针证实 alive 600 条无一 误伤）。轮数拉到 500 全绿。<strong>教训：断言统计目标前先算覆盖概率</strong> 差点把&quot;没删完&quot;误判成&quot;误删活人&quot;，方向正好相反。</li><li><strong>Ghosts() 的成本观两版通用</strong>。Rust :995 注释原话&quot;没有它，主动老化 其实没跑起来会是一次安静的失效&quot;。Go 版同款 RLock 全表扫，测试 与调试用，生产别开（ghost_gauge 默认关的理由）。</li></ol><h3 id="g6-起手-收官" tabindex="-1">G6 起手（收官） <a class="header-anchor" href="#g6-起手-收官" aria-label="Permalink to &quot;G6 起手（收官）&quot;">​</a></h3><p>Go 版 vs Rust 版同机压测（自写 <code>dnsq/</code> 打包器），结论进 <code>dnsproxi-go/LESSON.md</code>。对照你 Rust 版的性能预算：每查询一次 <code>Sketch.Increment</code>（4 次 Or + 4 次哈希）+ PutFull 锁内判决。压测维度： 无缓存/有缓存/准入 on/off/老化 on/off 五档 qps 与 P99，Rust/Go 各跑。</p><h2 id="g6-复盘-2026-10-10-实测完成-全课收官" tabindex="-1">G6 复盘（2026-10-10 实测完成，全课收官） <a class="header-anchor" href="#g6-复盘-2026-10-10-实测完成-全课收官" aria-label="Permalink to &quot;G6 复盘（2026-10-10 实测完成，全课收官）&quot;">​</a></h2><p>实装范围：<code>dnsq/</code>（Go 版 UDP 压测器：并发 worker、rate 限速、 P50/P90/P99 分位、PCG 种子）+ 五档同机压测 + <code>dnsproxi-go/LESSON.md</code> 毕业总结。</p><h3 id="实测结果-conc-16-dur-5s-全档零丢包" tabindex="-1">实测结果（conc=16, dur=5s, 全档零丢包） <a class="header-anchor" href="#实测结果-conc-16-dur-5s-全档零丢包" aria-label="Permalink to &quot;实测结果（conc=16, dur=5s, 全档零丢包）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>Go qps/P99</th><th>Rust qps/P99</th></tr></thead><tbody><tr><td>无缓存 ks=1000</td><td>10 924 / 4.5ms</td><td>12 439 / 5.1ms</td></tr><tr><td>缓存 on ks=1000</td><td>9 336 / 6.8ms</td><td>12 156 / 6.9ms</td></tr><tr><td>命中路径 ks=100</td><td>9 940 / 5.6ms</td><td>19 422 / 2.0ms</td></tr><tr><td>准入 on ks=5000</td><td>10 288 / 6.9ms</td><td>15 037 / 2.4ms</td></tr><tr><td>+主动老化</td><td>10 381 / 6.1ms</td><td>13 596 / 4.1ms</td></tr></tbody></table><p>这次数据表明几组负载下 Go 与 Rust 处于同一数量级，命中路径差距最大。以下原因只能作为后续 profiling 的假设，而不是由这组数据单独证明：临时上游 socket 可能限制吞吐；Go 的额外应答拷贝可能影响命中路径；GC 可能影响尾延迟。准入和老化几档的结果接近，但短时测试不能证明它们没有成本。具体实验条件与后续 GC 观察见 <code>dnsproxi-go/LESSON.md</code> 和 <code>labs/experiments/results-gc-2026-10-12.md</code>。</p><p><strong>翻车×2（都在压测器，不在被测系统）</strong>：① dnsq 的 <code>SetReadDeadline</code> 只设一次，第 2 包起 deadline 已过期 → 96% 假丢包， 差点把&quot;压测器坏了&quot;读成&quot;代理不行&quot;；② rate 公式把 dur 当分母（应为 <code>conc/rate</code> 秒/worker），限速 2000 实发 371。<strong>教训：压测器自己先要 过单 worker 零丢失这一关，再谈并发数据。</strong></p><h3 id="收官清单" tabindex="-1">收官清单 <a class="header-anchor" href="#收官清单" aria-label="Permalink to &quot;收官清单&quot;">​</a></h3><ul><li>[x] G1 wire/proxy（对照 D1）</li><li>[x] G2 cache（对照 D2）</li><li>[x] G3 容量+逐出（对照 D3/D4）</li><li>[x] G4 TinyLFU（对照 D5）</li><li>[x] G5 主动老化（对照 D6）</li><li>[x] G6 压测收官（对照 D7/L8）</li><li>[ ] P1-P5 练习包仍红着，等你动手：capstone 全绿不代表练习过关， 那些才是你自己写的部分。</li></ul><h2 id="g3-复盘-2026-10-09-实测完成" tabindex="-1">G3 复盘（2026-10-09 实测完成） <a class="header-anchor" href="#g3-复盘-2026-10-09-实测完成" aria-label="Permalink to &quot;G3 复盘（2026-10-09 实测完成）&quot;">​</a></h2><p>实装范围：<code>cache/evict.go</code>（keys+slot 反查表、xorshift64*、Floyd 抽样、 pickVictim/PutFull/removeSlot）+ <code>Cache</code> 结构扩展（max/SampleK/Seed + evictions/examined/admits/rejects 账本）+ main.go 接线（DNS_CACHE_MAX/ SAMPLE_K/SEED 三个 env、cache evict 日志（INFO 级））+ run.sh evict 场景。</p><h3 id="实测结果-3" tabindex="-1">实测结果 <a class="header-anchor" href="#实测结果-3" aria-label="Permalink to &quot;实测结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>结果</th></tr></thead><tbody><tr><td><code>go test -race -count=1 ./cache/</code></td><td>全绿（G3 测试 6 个：封顶/最冷者死/在位者刷新/无界/slot 一致性/并发）</td></tr><tr><td>evict 冒烟：max=2，查 ev1/ev2/ev3</td><td><code>msg:&quot;cache evict&quot; victim:&quot;ev1.test&quot; new:&quot;ev3.test&quot; policy:&quot;full-lru&quot; checked=2</code>，逐出链 ev1→ev2→ev3</td></tr><tr><td>上游计数</td><td>ev1×2、ev2×2、ev3×1，被逐出的名字重新走上游，正是逐出生效的判据</td></tr><tr><td>在位者刷新</td><td>50 连刷零逐出零拒绝（对照你 Rust 版 :1150 的语义）</td></tr></tbody></table><h3 id="go-vs-rust-实感-对照你-rust-版-d3-d4" tabindex="-1">Go vs Rust 实感（对照你 Rust 版 D3/D4） <a class="header-anchor" href="#go-vs-rust-实感-对照你-rust-版-d3-d4" aria-label="Permalink to &quot;Go vs Rust 实感（对照你 Rust 版 D3/D4）&quot;">​</a></h3><ol><li><strong>Entry.slot 字段 → 反向 map</strong>。Rust 把 slot 存在 Entry 里（逐出时 swap_remove + 修正被换位条目的 slot，一处写）；Go 版用 <code>map[Key]int</code> 反查表（同样一处写，但多一张表要同步）。三张表（keys/slot/m）必须 一起动，第一版 removeSlot 漏删 m，len=4 keys=3 m=4，容量上限静默失效， 被测试当场抓住。教训：<strong>Rust 的 struct 字段是编译器帮你绑定的不变量， Go 的平行 map 是你自己守的</strong>。</li><li><strong>AtomicU64 → 写锁升级</strong>。Rust 版命中时在读锁下 <code>fetch_max</code> 更新 last_access（&quot;读变写&quot;难题的原子解）；Go 的 map 没有原子，Get 命中 必须升级写锁。这就是你 Rust 课文 §&quot;严格 LRU&quot;那段说的代价在 Go 的 实相：<strong>没有原子可借时，读多写少的 RwLock 优势直接打折</strong>。第一版我 把 touch 留在 PutFull、Get 只读，端到端立刻翻车：ev2 刚命中却被逐出 （它的 last_access 还停在插入时刻）。&quot;命中必须变热&quot;不是优化，是 LRU 的定义。</li><li><strong>Floyd 抽样一行不差地抄</strong>。<code>for j in len-k..len { candidate = random(j+1); if dup { j } else { candidate } }</code> ：Rust 和 Go 逐字对应。这类算法 的正确策略就是信源码，别&quot;用自己的话重写&quot;。</li><li><strong>fake clock 注入</strong>。测试用 <code>NowMs = func() uint64 { return fc.ms }</code> 替换逻辑时钟，last_access 完全可控。你 Rust 版测试传 now_ms 闭包； Go 的包级 var 替换更粗暴（测试串行时才安全），但够用。</li></ol><h3 id="g4-起手" tabindex="-1">G4 起手 <a class="header-anchor" href="#g4-起手" aria-label="Permalink to &quot;G4 起手&quot;">​</a></h3><p>对照你 Rust 版 FreqSketch：TinyLFU 准入。Go 版 <code>cache/sketch.go</code>： count-min sketch（4 行 × 4bit 计数器，16 格打包进一个 uint64，位运算 Go/Rust 完全同构）+ doorkeeper bloom + 老化减半。入口：<code>DNS_CACHE_ADMIT</code> env。关键判据：候选人频率 vs 在位者频率，打不过就拒（rejects++）。</p><h2 id="g1-复盘-2026-10-09-实测完成" tabindex="-1">G1 复盘（2026-10-09 实测完成） <a class="header-anchor" href="#g1-复盘-2026-10-09-实测完成" aria-label="Permalink to &quot;G1 复盘（2026-10-09 实测完成）&quot;">​</a></h2><p>实装范围：wire/wire.go（header + ParseName 压缩指针）、main.go 的 Proxy （Run 循环、handleQuery、sinkhole、上游 2s deadline）、fake upstream + dig 冒烟（run.sh）。</p><h3 id="实测结果-4" tabindex="-1">实测结果 <a class="header-anchor" href="#实测结果-4" aria-label="Permalink to &quot;实测结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>结果</th></tr></thead><tbody><tr><td><code>go test -race ./...</code>（wire 6 测 + proxy 3 测）</td><td>全绿，race 0（wire 6 测 = TestHeaderRoundTrip/TooShort/NameBasic/NamePointer/NamePointerLoop/EncodeName）</td></tr><tr><td>dig 走 proxy 查 open.test → fake 上游</td><td>NOERROR + <code>A 10.0.0.1</code>（四跳通）</td></tr><tr><td><code>DNS_SINKHOLE=blocked.</code> 查 blocked.test</td><td><strong>NXDOMAIN，上游零包</strong></td></tr><tr><td>对照组 open.test 同实例</td><td>NOERROR（前缀匹配不误伤）</td></tr><tr><td>上游黑洞</td><td>handleQuery 2s deadline 后返回，无 goroutine 泄漏</td></tr></tbody></table><h3 id="go-vs-rust-实感-对照你-rust-版-dnsproxi-同功能" tabindex="-1">Go vs Rust 实感（对照你 Rust 版 dnsproxi 同功能） <a class="header-anchor" href="#go-vs-rust-实感-对照你-rust-版-dnsproxi-同功能" aria-label="Permalink to &quot;Go vs Rust 实感（对照你 Rust 版 dnsproxi 同功能）&quot;">​</a></h3><ol><li><strong>报文解析要显式检查边界</strong>。Rust 版的 <code>try_get</code> 返回错误，Go 的切片索引越界会 panic；Rust 普通索引也可能 panic。这与借用检查是不同的问题，Go 版 ParseName 在访问前检查位置。</li><li><strong>per-query 生命周期靠纪律</strong>。<code>tokio::spawn</code> 有 JoinHandle 管； <code>go handleQuery()</code> 谁也不等：Run 里 WaitGroup + ctx-close-监听口 <ul><li>入口 recover 三件套缺一不可。P3 问题 1 的实弹版（goroutine panic 防御）。</li></ul></li><li><strong>UDP deadline 是救命的</strong>。上游黑洞场景，没有 <code>SetDeadline</code> 的版本 goroutine 永久挂死（TestD1Timeout 3s 抓到）。L9 的 &quot;bound your resources&quot; 在 Go 的对应物 = 每个 socket 操作都带 deadline。</li><li><strong>冒烟踩坑</strong>：fake upstream 把整条 query 尾部（含 EDNS OPT）echo 回去再拼 answer、ARCOUNT 写 0 → dig 报 &quot;16 extra bytes / malformed&quot;。 hex dump + 手数偏移定位（多的 16 字节正好是拼上的 A 记录）。 修复 = 只 echo question 段。字节级协议调试方法论从 Rust D1 直接迁移。</li><li><strong>端口坑</strong>：macOS Chrome 常驻 UDP :5353（mDNS），run.sh 改用 15353/15300。对应 rs-lab 速查表&quot;环境本身要先标定&quot;：本机端口占用 先 <code>netstat -anv -p udp</code> 看一眼。</li></ol><h3 id="遗留-进-g2-前不必修" tabindex="-1">遗留（进 G2 前不必修） <a class="header-anchor" href="#遗留-进-g2-前不必修" aria-label="Permalink to &quot;遗留（进 G2 前不必修）&quot;">​</a></h3><ul><li>QDCount&gt;1 的查询 sinkhole 只看第一条 question（D1 语义已够）</li><li>ctx 取消后在飞 query 靠 WaitGroup 排空；G5 加主动老化时统一改 errgroup + 带超时 drain</li></ul>`,67)])])}const p=e(a,[["render",r]]);export{g as __pageData,p as default};
